import {shouldContinueToolLoop, accumulateUsage} from './orchestratorHelpers.js';
import type {ToolRegistry} from './tools/registry.js';
import type {ToolCall, UsageMetadata} from '../types/ai.js';

// All three conditions matter; dropping the registry check spins the tool loop.

const A_TOOL: ToolCall[] = [{id: 't1', name: 'lookup', input: {}}];
const REGISTRY = {} as ToolRegistry;

describe('shouldContinueToolLoop', () => {
  it('continues when the model requested a tool and a registry can run it', () => {
    expect(shouldContinueToolLoop('tool_use', A_TOOL, REGISTRY)).toBe(true);
  });

  it('stops when no registry is configured, whatever the model asked for', () => {
    expect(shouldContinueToolLoop('tool_use', A_TOOL, undefined)).toBe(false);
  });

  it('stops when the model named no tool', () => {
    expect(shouldContinueToolLoop('tool_use', [], REGISTRY)).toBe(false);
  });

  it('stops when the model finished for a reason other than tool use', () => {
    expect(shouldContinueToolLoop('end_turn', A_TOOL, REGISTRY)).toBe(false);
  });
});

describe('accumulateUsage', () => {
  it('sums token fields when both operands are defined', () => {
    const a: UsageMetadata = {inputTokens: 10, outputTokens: 4, totalTokens: 14};
    const b: UsageMetadata = {inputTokens: 25, outputTokens: 8, totalTokens: 33};
    expect(accumulateUsage(a, b)).toEqual({inputTokens: 35, outputTokens: 12, totalTokens: 47});
  });

  it('returns the defined side when one operand is undefined', () => {
    const usage: UsageMetadata = {inputTokens: 5, outputTokens: 2, totalTokens: 7};
    expect(accumulateUsage(undefined, usage)).toEqual(usage);
    expect(accumulateUsage(usage, undefined)).toEqual(usage);
  });

  it('returns undefined when both operands are undefined', () => {
    expect(accumulateUsage(undefined, undefined)).toBeUndefined();
  });
});
CHANGELOG.md:19:- **`afterModelResponse` now receives usage summed across every provider call in the turn, not only the final round.** For a turn that completed without tool calls the value is identical to before. For a turn that ran tool rounds, existing consumers will now record a larger number that covers the full cost of the turn — the increase is exactly what was previously uncounted. `undefined` is still passed when no round in the turn reported usage.
CHANGELOG.md:34:- `maxToolRounds` now counts executed rounds: the default of 5 runs 5 tool rounds, not 6. Raise it by one to keep the old count.
CHANGELOG.md:41:- `HalEngineConfig.transport` now accepts three optional extension points: `additionalRoutes` (mounts a router under `basePath`, unauthenticated), `rootRoutes` (mounts a router at `/`, after the `basePath` router and before the 404 catch-all), and `errorHandler` (replaces Express's default HTML error page). Pass none of them and the app is identical to before. See `docs/getting-started.md` for usage and the GDPR / NIS-2 notes that apply to unauthenticated routes.
CHANGELOG.md:43:- `OrchestratorHooks` gains an optional `onToolBudgetExhausted(session, budget)` hook, and `ToolBudgetInfo` (`{maxToolRounds, requestedTools}`) and `TOOL_BUDGET_EXHAUSTED` are exported. It fires when the model asks for a tool round `maxToolRounds` refuses, after the last provider call and before `afterModelResponse`. Return a sentence and the turn ends on it as an ordinary assistant entry, so the user sees a degraded answer instead of silence; the engine writes no prose of its own. Every exhausted run now also ends with a `{type: 'stop', stopReason: 'tool_budget_exhausted'}` chunk, a new value for the existing field rather than a new type, which the WebSocket transport sends nothing for. The turn still ends with `stream_end`, never `error`. Additive: with no hook installed, the wire is unchanged.
CHANGELOG.md:50:- `maxToolRounds` now bounds the tool rounds that are actually executed: at most `maxToolRounds` rounds run, and the provider is called at most `maxToolRounds + 1` times. Previously the loop ran one extra round whose tool results no provider call ever read, so the default of 5 executed 6 rounds; it now executes 5, and the sixth provider call still reads the fifth round's results. `maxToolRounds: 0` now means one provider call and no tool execution, a negative value behaves as 0, and a non-finite value falls back to the default. When the budget runs out, the engine logs one `warn` (`tool budget exhausted`) naming the tools it did not run. **Migration note**: no exported type or signature changes, but a tool with a side effect in that final, unread round no longer runs there; to restore the old count, raise `maxToolRounds` by one.
specs/hal-engine-config-hooks/spec.md:8:`OrchestratorHooks` is the engine's only lifecycle seam, and `HalEngineConfig.orchestrator.hooks` is the supported way to install it: `createHalEngine` forwards the set to `createChatOrchestrator`, so a hook a deployer passes through the factory reaches the running orchestrator rather than sitting unread on the config object. This spec pins that forwarding and the measured semantics the seam already carries, so the hook-based features that follow in this epic — transparency disclosure, audit and usage recording, human oversight, provider failover — specify against real behaviour rather than against what the hook names suggest.
specs/hal-engine-config-hooks/spec.md:16:- For a session that completes without error the hooks fire in the order `beforeSession` → `beforeUserInput` → `afterUserInput` → `beforeModelResponse` → `afterModelResponse` → `afterSession` ([validated by: fires the lifecycle hooks in documented order for a session that completes without error](../../src/config.test.ts#L132)).
specs/hal-engine-config-hooks/spec.md:17:- A `beforeSession` that throws reaches the caller as a rejection, and also runs `onError` with the thrown error and then `afterSession`, because the call sits inside the same `try`/`finally` as the rest of the turn. An `afterSession` hook called under this condition can infer the session never advanced past `beforeSession`: no user-input hooks ran, no model response was generated, and no tool rounds were started — a cleanup hook that allocates in `beforeSession` and frees in `afterSession` will therefore always see the allocation and the release on the same error path ([validated by: runs onError then afterSession when it throws, and still rejects to the caller](../../src/orchestration/chatOrchestrator.test.ts#L116)).
specs/hal-engine-config-hooks/spec.md:18:- `afterModelResponse` is called once per user message after the round loop exits and receives the `UsageMetadata` summed across every provider call in that turn, rather than only the final round's usage ([validated by: reports usage summed across every provider call when a turn runs through two tool rounds](../../src/orchestration/chatOrchestrator.acceptance.test.ts#L53)).
specs/hal-engine-config-hooks/spec.md:19:- When some rounds in a turn omit `usage`, `afterModelResponse` receives the sum of the rounds that reported it, and when no round in the turn reported `usage`, it receives `undefined` ([validated by: counts the rounds that reported usage when some omit it, and reports undefined when none did](../../src/orchestration/chatOrchestrator.acceptance.test.ts#L63)).

